package com.andye.warmod.antiair;import com.andye.warmod.silo.MissileSiloCollisionContext;import java.util.*;import net.fabricmc.fabric.api.event.lifecycle.v1.*;import net.minecraft.server.MinecraftServer;import net.minecraft.server.level.ServerLevel;public final class AntiAirFlightControllerManager{private static final Map<ServerLevel,LinkedHashMap<UUID,AntiAirFlightController>> ACTIVE=new WeakHashMap<>();private static boolean registered;private AntiAirFlightControllerManager(){}public static void register(){if(registered)return;ServerTickEvents.END_LEVEL_TICK.register(AntiAirFlightControllerManager::tick);ServerLifecycleEvents.SERVER_STOPPING.register(AntiAirFlightControllerManager::stop);ServerLifecycleEvents.SERVER_STOPPED.register(s->ACTIVE.clear());registered=true;}public static synchronized boolean canAccept(ServerLevel l){return ACTIVE.getOrDefault(l,new LinkedHashMap<>()).size()<AntiAirConstants.MAXIMUM_ACTIVE_INTERCEPTORS_PER_LEVEL;}public static synchronized boolean add(ServerLevel l,AntiAirFlightPlan p,MissileSiloCollisionContext c){if(!canAccept(l))return false;var map=ACTIVE.computeIfAbsent(l,x->new LinkedHashMap<>());if(map.containsKey(p.interceptorId()))return false;map.put(p.interceptorId(),new AntiAirFlightController(p,c));return true;}private static synchronized void tick(ServerLevel l){var map=ACTIVE.get(l);if(map==null)return;var it=map.values().iterator();while(it.hasNext()){var c=it.next();c.tick(l);if(c.completed())it.remove();}if(map.isEmpty())ACTIVE.remove(l);}private static synchronized void stop(MinecraftServer s){ACTIVE.clear();}}